sys_script_include.script:
var AttendeeUtils = Class.create();
AttendeeUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getAttendeeDetails: function() {
        var attendeeId = this.getParameter('sysparm_attendee_id');
        var gr = new GlideRecord('x_1790116_event_ma_attendee');

        gr.addQuery('number', attendeeId);
        gr.query();
        if (gr.next())
            var result = {
                first_name: gr.getValue('u_first_name'),
                last_name: gr.getValue('u_last_name'),
                email: gr.getValue('u_email'),
                contact_number: gr.getValue('u_contact_number'),
                event_id: gr.getDisplayValue('u_event_id'),
                sys_id: gr.getUniqueValue()
            };
        return JSON.stringify(result);
    },

    type: 'AttendeeUtils'
});
